(() => {
  'use strict';

  const STORAGE_KEY = 'merph:pwa:v1';
  const MS_DAY = 86400000;
  const LEVELS = {
    beginner: {name:'Beginner', run:0.5, pull:50, push:100, squat:150, rounds:10, pullPer:5, pushPer:10, squatPer:15, pullName:'Ring rows', pushName:'Modified push-ups'},
    advanced: {name:'Advanced', run:1, pull:50, push:100, squat:150, rounds:10, pullPer:5, pushPer:10, squatPer:15, pullName:'Pull-ups', pushName:'Push-ups'},
    pro: {name:'Pro', run:1, pull:100, push:200, squat:300, rounds:20, pullPer:5, pushPer:10, squatPer:15, pullName:'Pull-ups', pushName:'Push-ups'}
  };
  const ICONS = {
    activity:'<path d="M22 12h-4l-3 9L9 3l-3 9H2"/>',
    dashboard:'<rect x="3" y="3" width="7" height="9" rx="1"/><rect x="14" y="3" width="7" height="5" rx="1"/><rect x="14" y="12" width="7" height="9" rx="1"/><rect x="3" y="16" width="7" height="5" rx="1"/>',
    dumbbell:'<path d="m6.5 6.5 11 11m3-5-8 8m-9-9 8-8m-6 0 3 3m-6 0 3 3m12 9 3 3m-6 0 3 3"/>',
    trophy:'<path d="M8 21h8m-4-4v4m-5-18h10v7a5 5 0 0 1-10 0V3Zm0 3H4v2a4 4 0 0 0 4 4m9-6h3v2a4 4 0 0 1-4 4"/>',
    gift:'<rect x="3" y="8" width="18" height="13" rx="2"/><path d="M12 8v13M3 12h18M12 8H7a2.5 2.5 0 1 1 2.5-2.5L12 8Zm0 0h5a2.5 2.5 0 1 0-2.5-2.5L12 8Z"/>',
    chart:'<path d="M3 3v18h18M7 16l4-5 4 2 5-7"/>',
    settings:'<path d="M4 7h16M4 17h16M8 4v6m8 4v6"/>',
    user:'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>',
    chevron:'<path d="m9 18 6-6-6-6"/>',
    arrow:'<path d="M5 12h14m-7-7 7 7-7 7"/>',
    play:'<polygon points="6 3 20 12 6 21 6 3"/>',
    pause:'<rect x="5" y="4" width="5" height="16" rx="1"/><rect x="14" y="4" width="5" height="16" rx="1"/>',
    stop:'<rect x="5" y="5" width="14" height="14" rx="2"/>',
    check:'<path d="m5 12 5 5L20 7"/>',
    checkcircle:'<circle cx="12" cy="12" r="10"/><path d="m7 12 3 3 7-7"/>',
    circle:'<circle cx="12" cy="12" r="9"/>',
    timer:'<circle cx="12" cy="13" r="9"/><path d="M12 8v5l3 2M9 2h6"/>',
    calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>',
    flame:'<path d="M12 22a8 8 0 0 0 8-8c0-4-2-6-3-7 0 4-3 4-3 4C14 6 11 3 9 2c0 6-5 8-5 12a8 8 0 0 0 8 8Z"/><path d="M12 22a4 4 0 0 0 4-4c0-2-2-3-3-5-1 2-5 3-5 5a4 4 0 0 0 4 4Z"/>',
    flag:'<path d="M4 22V4m0 1c5-3 9 3 16 0v11c-7 3-11-3-16 0"/>',
    foot:'<path d="M8 15c-2 0-4 2-4 4s1 3 3 3c4 0 6-7 3-8-.6-.2-1.3 1-2 1Zm8-7c-2 0-4 2-4 4s1 3 3 3c4 0 6-7 3-8-.6-.2-1.3 1-2 1ZM5 11l1-2m2-2 1-2m9 0 1-2m-5 3 1-2"/>',
    medal:'<circle cx="12" cy="16" r="5"/><path d="M8.2 12 5 2h5l2 5 2-5h5l-3.2 10m-6 4 2 1 2-1"/>',
    coffee:'<path d="M4 8h13v7a5 5 0 0 1-5 5H9a5 5 0 0 1-5-5V8Zm13 1h2a3 3 0 0 1 0 6h-2M2 22h19M7 2v3M12 2v3"/>',
    shirt:'<path d="m16 3 5 4-3 5-3-2v11H9V10l-3 2-3-5 5-4c1 2 7 2 8 0Z"/>',
    download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',
    upload:'<path d="M12 16V4m-5 5 5-5 5 5M4 17v4h16v-4"/>',
    plus:'<path d="M12 5v14M5 12h14"/>',
    minus:'<path d="M5 12h14"/>',
    refresh:'<path d="M20 11a8 8 0 0 0-14-5L3 9m0-5v5h5M4 13a8 8 0 0 0 14 5l3-3m0 5v-5h-5"/>',
    lock:'<rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',
    spark:'<path d="m12 3 1.8 6.2L20 11l-6.2 1.8L12 19l-1.8-6.2L4 11l6.2-1.8L12 3ZM20 19v4m-2-2h4"/>',
    shield:'<path d="m12 22 8-4V6l-8-4-8 4v12l8 4Zm-4-10 3 3 5-6"/>',
    info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v6m0-10h.01"/>',
    edit:'<path d="m16 5 3 3M3 21l4-1 12-12a2.1 2.1 0 0 0-3-3L4 17l-1 4Z"/>',
    trash:'<path d="M3 6h18M8 6V4h8v2m3 0-1 15H6L5 6m5 4v7m4-7v7"/>',
    close:'<path d="M18 6 6 18M6 6l12 12"/>',
    wifi:'<path d="M2 9a16 16 0 0 1 20 0M5 13a11 11 0 0 1 14 0m-11 4a6 6 0 0 1 8 0m-4 4h.01"/>',
    off:'<path d="m2 2 20 20M2 9a16 16 0 0 1 7-3m5 0a16 16 0 0 1 8 3M5 13a11 11 0 0 1 4-2m6 0a11 11 0 0 1 4 2M8 17a6 6 0 0 1 8 0m-4 4h.01"/>',
    users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m12-9a4 4 0 1 0-6 0m8 3a4 4 0 0 1 6 4v2m-5-17a4 4 0 0 1 0 8"/>',
    bolt:'<path d="m13 2-9 12h7l-1 8 10-12h-7l0-8Z"/>',
    home:'<path d="m3 10 9-7 9 7v11h-6v-7H9v7H3V10Z"/>',
    save:'<path d="M4 3h14l3 3v15H3V3h1Zm3 0v6h10V3m-9 18v-8h8v8"/>',
    target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',
    external:'<path d="M13 4h7v7M20 4l-9 9M20 13v7H4V4h7"/>',
    menu:'<path d="M4 6h16M4 12h16M4 18h16"/>'
  };
  const icon = (name, size=18) => `<svg class="icon" aria-hidden="true" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${ICONS[name]||ICONS.activity}</svg>`;
  const safe = value => String(value ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const uid = () => (globalThis.crypto?.randomUUID ? crypto.randomUUID() : `id-${Date.now()}-${Math.random().toString(36).slice(2)}`);
  const today = () => { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; };
  const toUTC = s => Date.UTC(...String(s).slice(0,10).split('-').map((x,i)=>i===1?Number(x)-1:Number(x)));
  const dayAdd = (s,n) => new Date(toUTC(s)+n*MS_DAY).toISOString().slice(0,10);
  const monday = s => { const d = new Date(toUTC(s)); return dayAdd(s,-((d.getUTCDay()+6)%7)); };
  const weekIndex = (d,start) => Math.floor((toUTC(d)-toUTC(start))/(7*MS_DAY));
  const formatDate = s => {const d = new Date(toUTC(s));return d.toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'});};
  const clamp = (n,min,max) => Math.min(max,Math.max(min,n));
  const num = v => Math.max(0, Number(v)||0);
  const initials = name => String(name||'You').trim().split(/\s+/).slice(0,2).map(w=>w[0]||'').join('').toUpperCase();
  const makeWorkout = profile => ({level:profile.level||'advanced',type:'training',scale:0.25,vest:false,vestWeight:0,first:false,last:false,rounds:[],manual:{pull:0,push:0,squat:0},elapsedMs:0,runningSince:null,notes:''});
  const defaultState = () => {
    const profile = {id:uid(),name:'You',team:'North Shop',level:'advanced'};
    return {schema:1, profiles:[profile],activeProfileId:profile.id,challenge:{name:'MERPH Fall Challenge',group:'MERPH Crew',startDate:monday(today()),weeks:7},workouts:{[profile.id]:makeWorkout(profile)},sessions:[],activities:[],rewards:[{id:'bronze',name:'Bronze',description:'Digital achievement badge',xp:200,icon:'medal'},{id:'silver',name:'Silver',description:'Coffee or snack voucher',xp:400,icon:'coffee'},{id:'gold',name:'Gold',description:'Challenge merchandise',xp:600,icon:'shirt'},{id:'champion',name:'Champion',description:'Premium prize eligibility',xp:750,icon:'trophy'}],claims:[]};
  };
  const parseState = () => {
    try {
      const stored = JSON.parse(localStorage.getItem(STORAGE_KEY));
      if (stored && stored.schema===1 && Array.isArray(stored.profiles) && stored.profiles.length && Array.isArray(stored.sessions) && Array.isArray(stored.activities) && stored.challenge && Array.isArray(stored.rewards) && Array.isArray(stored.claims) && stored.workouts && typeof stored.workouts==='object') return stored;
    } catch(e) { console.warn('Local data could not be loaded',e); }
    return defaultState();
  };
  let state = parseState();
  let page = ['dashboard','workout','compete','rewards','history','settings'].includes(location.hash.slice(1)) ? location.hash.slice(1) : 'dashboard';
  let modal = null;
  let deferredInstall = null;
  let online = navigator.onLine;

  function persist() { try {localStorage.setItem(STORAGE_KEY,JSON.stringify(state));return true;}catch(e){toast('Saving failed. Your browser storage may be full. Export a backup.',true);return false;} }
  function activeProfile(){return state.profiles.find(p=>p.id===state.activeProfileId)||state.profiles[0];}
  function activeWorkout(){const p=activeProfile(); if (!state.workouts[p.id])state.workouts[p.id]=makeWorkout(p);return state.workouts[p.id];}
  function levelFor(w){const base=LEVELS[w.level]||LEVELS.advanced;if(w.type==='final')return base;const scale=[.25,.5,.75,1].includes(Number(w.scale))?Number(w.scale):.25;const rounds=Math.max(1,Math.round(base.rounds*scale));return {...base,rounds,run:Number((base.run*scale).toFixed(3)),pull:rounds*base.pullPer,push:rounds*base.pushPer,squat:rounds*base.squatPer};}
  function doneCount(w){return new Set(w.rounds.filter(r=>Number.isInteger(r)&&r>=0&&r<levelFor(w).rounds)).size;}
  function repTotal(w,key){const lv=levelFor(w);return Math.min(lv[key],doneCount(w)*lv[key==='pull'?'pullPer':key==='push'?'pushPer':'squatPer']+num(w.manual?.[key]));}
  function percent(w){const lv=levelFor(w);const repsTotal=repTotal(w,'pull')/lv.pull+repTotal(w,'push')/lv.push+repTotal(w,'squat')/lv.squat;return Math.round((Number(!!w.first)+Number(!!w.last))*20 + repsTotal*20);}
  function elapsed(w){return Math.max(0,Math.floor((num(w.elapsedMs)+(w.runningSince?Math.max(0,Date.now()-w.runningSince):0))/1000));}
  function timeFmt(sec){const h=Math.floor(sec/3600),m=Math.floor((sec%3600)/60),s=sec%60;return [h,m,s].map(x=>String(x).padStart(2,'0')).join(':');}
  function shortTime(sec){return sec ? timeFmt(sec) : 'Untimed';}
  function weekNow(){return weekIndex(today(),state.challenge.startDate);}
  function availableXP(){const n=weekNow();return clamp(n+1,0,6)*100+(n>=6?200:0);}
  function profileSessions(pid=activeProfile().id){return state.sessions.filter(s=>s.profileId===pid);}
  function profileActivities(pid=activeProfile().id){return state.activities.filter(a=>a.profileId===pid);}
  function xpFor(pid=activeProfile().id){return profileSessions(pid).reduce((n,s)=>n+num(s.xp),0)+profileActivities(pid).reduce((n,a)=>n+num(a.xp),0);}
  function xpWeekly(pid,week){return profileSessions(pid).filter(s=>s.week===week&&s.type==='training').reduce((n,s)=>n+num(s.xp),0)+profileActivities(pid).filter(a=>a.week===week).reduce((n,a)=>n+num(a.xp),0);}
  function trainingCount(pid,week){return profileSessions(pid).filter(s=>s.week===week&&s.type==='training').length;}
  function activityExists(pid,week,kind){return state.activities.some(a=>a.profileId===pid&&a.week===week&&a.kind===kind);}
  function percentOf(value,max){return max<=0?0:clamp(Math.round(value/max*100),0,100);}
  function toast(message,isError=false){const root=document.getElementById('toast-layer');if(!root)return;const div=document.createElement('div');div.className='toast';if(isError){div.style.background='#43252a';div.style.borderColor='#9d5d60';}div.textContent=message;root.appendChild(div);setTimeout(()=>div.remove(),3400);}
  function badge(text,variant=''){return `<span class="badge ${variant?'badge-'+variant:''}">${safe(text)}</span>`;}
  function progress(value,variant=''){return `<div class="progress ${variant==='amber'?'amber-bar':variant==='blue'?'blue-bar':''}" role="progressbar" aria-valuenow="${clamp(Math.round(value),0,100)}" aria-valuemin="0" aria-valuemax="100"><span style="width:${clamp(value,0,100)}%"></span></div>`;}
  function cardHeader(title,subtitle='',ic=''){return `<div class="card-head"><div><h2>${title}</h2>${subtitle?`<p class="card-sub">${subtitle}</p>`:''}</div>${ic?`<span class="card-head-icon">${icon(ic)}</span>`:''}</div>`;}
  function pageHeading(upper,title,subtitle,button=''){return `<div class="page-heading"><div><div class="overline">${upper}</div><h1>${title}</h1><p>${subtitle}</p></div>${button}</div>`;}
  function ring(pct,size=195){const r=69,circ=2*Math.PI*r;return `<div class="ring-wrap"><svg width="${size}" height="${size}" viewBox="0 0 180 180" aria-label="${pct}% complete" role="img"><circle class="ring-track" cx="90" cy="90" r="69" stroke-width="14" fill="none"/><circle class="ring-arc" cx="90" cy="90" r="69" stroke-width="14" stroke-dasharray="${circ}" stroke-dashoffset="${circ*(1-pct/100)}" stroke-linecap="round" transform="rotate(-90 90 90)" fill="none"/><text x="90" y="87" text-anchor="middle" class="ring-value">${pct}%</text><text x="90" y="106" text-anchor="middle" class="ring-label">COMPLETE</text></svg></div>`;}
  function navs(){return [{id:'dashboard',label:'Dashboard',ico:'dashboard'},{id:'workout',label:'Workout',ico:'dumbbell'},{id:'compete',label:'Compete',ico:'trophy'},{id:'rewards',label:'Rewards',ico:'gift'},{id:'history',label:'History',ico:'chart'},{id:'settings',label:'Settings',ico:'settings'}];}
  function navButton(n,mobile=false){return `<button class="${mobile?'':'nav-'}${mobile?'':'btn'} ${page===n.id?'active':''}" data-nav="${n.id}" aria-current="${page===n.id?'page':'false'}">${icon(n.ico)}<span>${safe(n.label)}</span>${!mobile&&page===n.id?`<span class="nav-trail">${icon('chevron',15)}</span>`:''}</button>`;}
  function layout(){const p=activeProfile(),w=activeWorkout(),week=weekNow(),xp=xpFor();let content='';switch(page){case 'dashboard':content=dashboard();break;case 'workout':content=workoutScreen();break;case 'compete':content=competeScreen();break;case 'rewards':content=rewardsScreen();break;case 'history':content=historyScreen();break;case 'settings':content=settingsScreen();break;}
    return `<div class="app-shell"><aside class="sidebar"><a href="#dashboard" data-nav="dashboard" class="brand"><span class="brand-mark">M<span>.</span></span><span><div class="brand-name">MERPH</div><div class="brand-subtitle">CHALLENGE TRACKER</div></span></a><div><div class="nav-section">WORKSPACE</div><div class="nav-list">${navs().map(n=>navButton(n)).join('')}</div></div><div class="side-foot"><div class="challenge-mini"><div class="row between"><span class="upper green">Current challenge</span>${icon('flag',15)}</div><h3 style="margin-top:9px">${safe(state.challenge.name)}</h3><p class="small muted" style="margin-top:5px">${week<0?'Starts soon':week<=6?`Week ${week+1} of 7`:'Challenge finished'}</p>${progress(percentOf(xp,800))}<div class="row between tiny muted"><span>${xp} XP earned</span><span>800 XP goal</span></div></div><button class="side-user" data-action="profiles"><span class="avatar">${safe(initials(p.name))}</span><span style="flex:1;min-width:0"><strong style="display:block;white-space:nowrap;text-overflow:ellipsis;overflow:hidden">${safe(p.name)}</strong><small class="muted">${safe(p.team)}</small></span>${icon('chevron',17)}</button></div></aside><main class="main-area"><div class="mobile-head"><a href="#dashboard" class="brand" data-nav="dashboard"><span class="brand-mark">M<span>.</span></span><span><span class="brand-name" style="display:block">MERPH</span><span class="brand-subtitle" style="display:block">CHALLENGE TRACKER</span></span></a><div class="row"><span class="top-pill">${online?`<span class="dot"></span> Local demo`:`${icon('off',13)} Offline`}</span><button class="icon-button" aria-label="Profiles" data-action="profiles">${icon('user',18)}</button></div></div><div class="topbar"><div class="breadcrumb">Workspace ${icon('chevron',14)} <strong>${safe(navs().find(n=>n.id===page)?.label||'Dashboard')}</strong></div><div class="top-actions"><span class="top-pill">${online?`<span class="dot"></span> Local-only demo`:`${icon('off',13)} Offline ready`}</span><button class="icon-button" title="Export backup" aria-label="Export backup" data-action="export">${icon('download',18)}</button><button class="icon-button" title="Profile" aria-label="Profiles" data-action="profiles">${icon('user',18)}</button></div></div><div class="content">${content}<p class="footer-note">MERPH v1.0 · Offline ready · Data is stored only on this device · Demo rankings are not live</p></div></main><nav class="mobile-nav" aria-label="Primary navigation">${navs().filter(n=>n.id!=='settings').map(n=>navButton(n,true)).join('')}</nav></div>${modal?renderModal():''}`;
  }
  function render(){document.getElementById('app').innerHTML=layout();tick();}
  function navigate(next){if(!navs().some(n=>n.id===next))return;page=next;location.hash=next;modal=null;render();window.scrollTo({top:0,behavior:'instant'});}

  function dashboard(){const p=activeProfile(),w=activeWorkout(),lv=levelFor(w),week=weekNow(),weekGood=week>=0&&week<6,earned=xpFor(),weekly=weekGood?xpWeekly(p.id,week):0,training=weekGood?trainingCount(p.id,week):0,remaining=Math.max(0,100-weekly),next=state.rewards.filter(r=>earned<r.xp).sort((a,b)=>a.xp-b.xp)[0],recent=profileSessions().slice().sort((a,b)=>b.savedAt-a.savedAt).slice(0,3),daysLeft=Math.max(0,Math.ceil((toUTC(dayAdd(state.challenge.startDate,48))-toUTC(today()))/MS_DAY));
    return `<div class="stack"><section class="hero"><div class="hero-inner"><div class="overline">${week<0?'UPCOMING CHALLENGE':week>=7?'CHALLENGE COMPLETE':`WEEK ${week+1} OF 7 · KEEP SHOWING UP`}</div><h1 style="margin-top:12px">Stronger every round<span class="green">.</span></h1><p>Track your Murph training, hit your weekly goals, and build momentum toward the final challenge.</p><div class="hero-actions"><button class="btn btn-primary" data-nav="workout">${icon('play',16)} ${percent(w)>0?'Continue workout':'Start a workout'} ${icon('arrow',15)}</button><button class="btn btn-secondary" data-nav="compete">${icon('users',17)} View standings</button></div></div></section>
    <div class="grid grid-3"><section class="card stat-card"><div class="stat-top"><span>Total earned</span><span class="stat-icon">${icon('bolt',16)}</span></div><div class="stat-num green numeric">${earned}<span style="font-size:14px;color:#748c95"> XP</span></div><div class="stat-foot">${percentOf(earned,800)}% of 800 possible</div></section><section class="card stat-card"><div class="stat-top"><span>This week's training</span><span class="stat-icon">${icon('dumbbell',17)}</span></div><div class="stat-num numeric">${weekGood?Math.min(training,3):'—'} <span style="color:#7e939e;font-size:17px">/ 3</span></div><div class="stat-foot">${weekGood?`${remaining} weekly XP still available`:'Outside preparation weeks'}</div></section><section class="card stat-card"><div class="stat-top"><span>Final challenge</span><span class="stat-icon">${icon('calendar',17)}</span></div><div class="stat-num numeric">${daysLeft}<span style="font-size:14px;color:#8196a1"> days</span></div><div class="stat-foot">Ends ${formatDate(dayAdd(state.challenge.startDate,48))}</div></section></div>
    <div class="grid dashboard-grid"><div class="stack"><section class="card">${cardHeader('Active workout',`${lv.name} level · ${w.type==='final'?'Final event':`${Math.round(Number(w.scale||.25)*100)}% training session`}`,'target')}<div class="grid grid-2" style="align-items:center"><div>${ring(percent(w))}</div><div class="stack gap-12"><div class="exercise-row"><div class="row"><strong>${safe(lv.pullName)}</strong><span>${repTotal(w,'pull')}/${lv.pull}</span></div>${progress(percentOf(repTotal(w,'pull'),lv.pull))}</div><div class="exercise-row"><div class="row"><strong>${safe(lv.pushName)}</strong><span>${repTotal(w,'push')}/${lv.push}</span></div>${progress(percentOf(repTotal(w,'push'),lv.push))}</div><div class="exercise-row"><div class="row"><strong>Air squats</strong><span>${repTotal(w,'squat')}/${lv.squat}</span></div>${progress(percentOf(repTotal(w,'squat'),lv.squat))}</div><button data-nav="workout" class="btn btn-outline btn-wide">Open tracker ${icon('arrow',15)}</button></div></div></section>
    <section class="card">${cardHeader('Weekly activity','Points recorded during the six training weeks','chart')}${weekChart()}</section></div>
    <div class="stack"><section class="card">${cardHeader('Weekly XP checklist',weekGood?`Week ${week+1} · 100 points available`:'Available during training weeks','checkcircle')}<div class="stack" style="gap:14px"><div class="row between"><div><strong class="small">Qualifying workouts</strong><p class="tiny muted">${Math.min(training,3)} of 3 complete · up to 60 XP</p></div>${badge(`${Math.min(training,3)*20}/60 XP`)}</div>${progress(Math.min(training,3)/3*100)}<div class="row between"><div><strong class="small">Weekly goal</strong><p class="tiny muted">Automatically earned at 3 sessions</p></div>${badge(training>=3&&weekGood?'20 XP':'0/20 XP',training>=3?'':'grey')}</div><div class="row between"><div><strong class="small">Progress check-in</strong><p class="tiny muted">One entry per week · 10 XP</p></div><button data-action="activity" data-kind="checkin" class="btn ${weekGood&&!activityExists(p.id,week,'checkin')?'btn-outline':'btn-secondary'} btn-sm" ${!weekGood||activityExists(p.id,week,'checkin')?'disabled':''}>${activityExists(p.id,week,'checkin')?'Done':'Log +10'}</button></div><div class="row between"><div><strong class="small">Recovery / mobility</strong><p class="tiny muted">One entry per week · 10 XP</p></div><button data-action="activity" data-kind="recovery" class="btn ${weekGood&&!activityExists(p.id,week,'recovery')?'btn-outline':'btn-secondary'} btn-sm" ${!weekGood||activityExists(p.id,week,'recovery')?'disabled':''}>${activityExists(p.id,week,'recovery')?'Done':'Log +10'}</button></div><div class="row between" style="padding-top:3px"><strong class="small">Weekly XP</strong><strong class="green numeric">${weekly} / 100</strong></div>${progress(weekly)}</div></section>
    <section class="card">${cardHeader('Next reward',next?'Your next unlock is coming up':'All reward tiers unlocked','gift')}${next?`<div class="reward-tile"><div class="reward-icon">${icon(next.icon||'gift',23)}</div><div style="min-width:0;flex:1"><strong>${safe(next.name)}</strong><p class="tiny muted">${safe(next.description)}</p></div></div><div class="row between small" style="margin:16px 0 8px"><span class="muted">${earned} / ${next.xp} XP</span><strong class="amber">${Math.max(0,next.xp-earned)} to go</strong></div>${progress(percentOf(earned,next.xp),'amber')}`:`<p class="muted small">All milestones achieved. Claim your prizes in Rewards.</p>`}<button data-nav="rewards" class="btn btn-outline btn-wide" style="margin-top:17px">View reward catalog ${icon('arrow',15)}</button></section>
    <section class="card">${cardHeader('Recent sessions','Your latest completed workouts','timer')}${recent.length?recent.map(s=>`<div class="list-record"><span class="record-icon">${icon(s.type==='final'?'trophy':'dumbbell',19)}</span><div class="record-main"><div class="record-title">${safe(LEVELS[s.level]?.name||'Workout')} ${s.type==='final'?'Final':'Training'}</div><p class="record-sub">${formatDate(s.date)} · ${shortTime(s.duration)}</p></div><strong class="green small">+${s.xp} XP</strong></div>`).join(''):`<div class="empty-state"><div class="empty-illustration">${icon('dumbbell',25)}</div><strong>No sessions yet</strong><p class="small">Start a workout and save your first result.</p></div>`}</section></div></div></div>`;
  }
  function weekChart(){const me=activeProfile().id;const widths=60, max=100;const bars=Array.from({length:6},(_,i)=>({week:i,val:xpWeekly(me,i)}));return `<div class="chart-box"><svg viewBox="0 0 500 165" role="img" aria-label="XP per training week"><line class="chart-grid" x1="37" y1="23" x2="483" y2="23"/><line class="chart-grid" x1="37" y1="75" x2="483" y2="75"/><line class="chart-grid" x1="37" y1="128" x2="483" y2="128"/><text class="chart-label" x="2" y="27">100</text><text class="chart-label" x="9" y="79">50</text><text class="chart-label" x="17" y="132">0</text>${bars.map((b,i)=>{const h=b.val/max*105;const x=57+i*70;return `<rect x="${x}" y="${128-h}" width="37" height="${h}" rx="5" fill="${i===clamp(weekNow(),0,5)?'#abf1bd':'#548d71'}"/><text class="chart-label" x="${x+18.5}" y="149" text-anchor="middle">W${i+1}</text>${b.val?`<text x="${x+18.5}" y="${119-h}" font-family="sans-serif" text-anchor="middle" font-size="10" fill="#aaf6c0">${b.val}</text>`:''}`}).join('')}</svg></div><div class="row between" style="margin-top:3px"><span class="small muted">Total challenge progress</span><strong class="small green">${xpFor(me)} / 800 XP</strong></div>${progress(percentOf(xpFor(me),800))}`;}

  function workoutScreen(){const w=activeWorkout(),lv=levelFor(w),complete=percent(w)===100,week=weekNow(),alreadyFinal=profileSessions().some(s=>s.type==='final'&&s.xp>0);const hasAny=percent(w)>0||w.elapsedMs>0||!!w.runningSince;
    return `<div class="stack">${pageHeading('LIVE TRAINING','Every rep counts.','Track your workout in real time. Everything saves automatically on this device.',badge('Autosave on this device'))}
    <div class="grid workout-grid"><div class="stack"><section class="card">${cardHeader('Choose your level','Changing levels starts a fresh unsaved workout','shield')}<div class="level-selector">${Object.entries(LEVELS).map(([key,c])=>`<button class="level-choice ${w.level===key?'selected':''}" data-action="level" data-level="${key}" aria-pressed="${w.level===key}"><strong>${safe(c.name)}</strong><span class="small">${c.pull} / ${c.push} / ${c.squat}</span><span class="tiny">${c.run} mi × 2</span></button>`).join('')}</div><div class="segment" style="margin-top:15px"><button class="${w.type==='training'?'active':''}" data-action="workout-type" data-type="training">Training session</button><button class="${w.type==='final'?'active':''}" data-action="workout-type" data-type="final">Final event</button></div>${w.type==='training'?`<div style="margin-top:14px"><div class="row between" style="margin-bottom:8px"><strong class="small">Training target</strong><span class="tiny muted">Scaled from full challenge</span></div><div class="segment">${[.25,.5,.75,1].map(scale=>`<button class="${Number(w.scale||.25)===scale?'active':''}" data-action="scale" data-scale="${scale}">${Math.round(scale*100)}%</button>`).join('')}</div><p class="module-note" style="margin-top:8px">Training targets are scaled and adjustable; final event always uses 100% of the selected level.</p></div>`:''}${w.level!=='beginner'?`<div style="margin-top:14px" class="stack gap-8"><label class="toggle-label"><input type="checkbox" data-field="vest" ${w.vest?'checked':''}> Log weighted vest use (optional)</label>${w.vest?`<div class="field"><label for="vest-weight">Vest weight (lb)</label><input style="max-width:120px" id="vest-weight" data-field="vest-weight" type="number" min="0" max="150" step="0.5" value="${num(w.vestWeight)}" /></div>`:''}</div>`:''}${w.type==='final'?`<div class="notice warn" style="margin-top:12px">${icon('info',16)} Final event XP is awarded only during Week 7, once per participant. You can still practice and save a final attempt earlier.</div>`:''}</section>
    <section class="card">${cardHeader('Opening run',`${lv.run} ${lv.run===1?'mile':'mile'} · ${w.first?'Completed':'Not completed'}`,'foot')}${runRow('first',w.first,lv.run)}</section>
    <section class="card">${cardHeader('Exercise rounds',`${lv.rounds} rounds · ${lv.pullPer} ${lv.pullName.toLowerCase()}, ${lv.pushPer} push-ups, ${lv.squatPer} squats`,'dumbbell')}<div class="row between" style="margin-bottom:14px"><div class="small muted">Tap each completed round</div><strong class="green numeric">${doneCount(w)} / ${lv.rounds}</strong></div><div class="rounds">${Array.from({length:lv.rounds},(_,i)=>`<button class="round-btn ${w.rounds.includes(i)?'checked':''}" data-action="round" data-round="${i}" aria-label="Round ${i+1} ${w.rounds.includes(i)?'complete':'incomplete'}" aria-pressed="${w.rounds.includes(i)}">${icon(w.rounds.includes(i)?'check':'circle',17)}<span>${i+1}</span></button>`).join('')}</div><p class="module-note" style="margin-top:14px">Completing a round adds ${lv.pullPer} ${lv.pullName.toLowerCase()}, ${lv.pushPer} push-ups, and ${lv.squatPer} squats together. Use manual adjustments below for partial sets or extra reps.</p></section>
    <section class="card">${cardHeader('Repetition tracker','Manual adjustments are added to checked rounds','target')}${[['pull',lv.pullName,lv.pull],['push',lv.pushName,lv.push],['squat','Air squats',lv.squat]].map(([key,name,target])=>`<div class="rep-control"><div class="rep-name"><strong>${safe(name)}</strong><small>${target} reps goal · +${num(w.manual[key])} manual</small></div><div class="rep-number"><span class="green">${repTotal(w,key)}</span><span class="muted"> / ${target}</span></div><div class="mini-stepper"><button aria-label="Remove 5 ${safe(name)}" data-action="reps" data-key="${key}" data-delta="-5">−5</button><button aria-label="Add 5 ${safe(name)}" data-action="reps" data-key="${key}" data-delta="5">+5</button><button aria-label="Add 10 ${safe(name)}" data-action="reps" data-key="${key}" data-delta="10">+10</button></div></div>`).join('')}</section>
    <section class="card">${cardHeader('Closing run',`${lv.run} ${lv.run===1?'mile':'mile'} · ${w.last?'Completed':'Not completed'}`,'flag')}${runRow('last',w.last,lv.run)}</section></div>
    <div class="stack workout-sticky"><section class="timer-box"><div class="upper muted">ELAPSED WORKOUT TIME</div><div class="timer-time numeric" data-timer-time>${timeFmt(elapsed(w))}</div><div class="timer-buttons"><button class="btn btn-primary" data-action="timer-toggle">${icon(w.runningSince?'pause':'play',17)} ${w.runningSince?'Pause':elapsed(w)>0?'Resume':'Start timer'}</button><button class="btn btn-outline" data-action="timer-reset" title="Reset timer only">${icon('refresh',16)} Reset</button></div></section>
    <section class="card">${cardHeader('Workout progress',`${lv.name} · ${w.type==='final'?'Final event':`${Math.round(Number(w.scale||.25)*100)}% Training`}`,'activity')}${ring(percent(w),190)}<div class="row between" style="margin:2px 0 10px"><span class="small muted">Completed rounds</span><strong class="small numeric">${doneCount(w)} of ${lv.rounds}</strong></div>${progress(percent(w))}<div class="grid grid-2" style="margin:17px 0 15px"><div><div class="upper muted">Runs</div><strong class="numeric" style="font-size:19px">${Number(w.first)+Number(w.last)} / 2</strong></div><div><div class="upper muted">All repetitions</div><strong class="numeric" style="font-size:19px">${repTotal(w,'pull')+repTotal(w,'push')+repTotal(w,'squat')} / ${lv.pull+lv.push+lv.squat}</strong></div></div><div class="field"><label for="workout-notes">Session notes / final reflection</label><textarea id="workout-notes" data-field="workout-notes" placeholder="How did your workout go? What would you improve?">${safe(w.notes||'')}</textarea></div><div class="stack gap-8" style="margin-top:13px"><button class="btn btn-primary btn-wide" data-action="finish-workout" ${!complete?'disabled':''}>${icon('checkcircle',18)} ${complete?'Save completed workout':'Complete all goals to save'}</button><button class="btn btn-outline btn-wide" data-action="reset-workout">${icon('refresh',16)} Reset unsaved workout</button></div>${complete?`<p class="module-note green" style="margin-top:12px">${icon('spark',15)} All movements completed — ready to save! ${alreadyFinal&&w.type==='final'?'Final event XP has already been awarded.':''}</p>`:`<p class="module-note" style="margin-top:12px">Check off both runs and meet each rep target to finish. You can pause and return later.</p>`}</section>
    <section class="notice info">${icon('info',16)} The timer keeps counting elapsed time when the app is backgrounded. Browser data remains on this device only; export a backup from Settings.</section></div></div></div>`;
  }
  function runRow(key,checked,miles){return `<button class="run-check ${checked?'done':''}" data-action="run" data-run="${key}" aria-pressed="${checked}"><span class="check-icon">${icon('check',18)}</span><span style="flex:1"><strong>${key==='first'?'Start strong':'Finish strong'}</strong><small>${miles} ${miles===1?'mile':'mile'} ${key==='first'?'opening':'closing'} run</small></span>${icon(checked?'checkcircle':'chevron',18)}</button>`;}

  function standings(){const max=Math.max(100,availableXP());const local=state.profiles.map(p=>({id:p.id,name:p.name,team:p.team||'Unaffiliated',xp:xpFor(p.id),pct:percentOf(xpFor(p.id),max),demo:false}));const demo=[{id:'demo-1',name:'Avery P.',team:'Studio Team',pct:87,demo:true},{id:'demo-2',name:'Jordan R.',team:'North Shop',pct:72,demo:true},{id:'demo-3',name:'Morgan L.',team:'Production',pct:62,demo:true},{id:'demo-4',name:'Casey M.',team:'Studio Team',pct:43,demo:true}].map(p=>({...p,xp:Math.round(max*p.pct/100)}));return {people:[...local,...demo].sort((a,b)=>b.pct-a.pct),max};}
  function competeScreen(){const {people,max}=standings();const teams=Object.values(people.reduce((acc,p)=>{if(!acc[p.team])acc[p.team]={name:p.team,members:[],pct:0};acc[p.team].members.push(p);return acc;},{})).map(t=>({...t,pct:Math.round(t.members.reduce((s,p)=>s+p.pct,0)/t.members.length)})).sort((a,b)=>b.pct-a.pct);const groupPct=people.length?Math.round(people.reduce((s,p)=>s+p.pct,0)/people.length):0;
    return `<div class="stack">${pageHeading('GROUP COMPETITION','Better together.','Individual goals. Shared momentum. Friendly competition.')}
    <div class="notice info">${icon('info',17)} <span><strong>This is a local demo leaderboard.</strong> ${state.profiles.length} profile(s) on this device; the other participants are simulated. Progress does not sync between phones.</span></div>
    <div class="grid grid-3"><section class="card stat-card"><div class="stat-top"><span>Participants</span>${icon('users',17)}</div><div class="stat-num numeric">${people.length}</div><div class="stat-foot">${state.profiles.length} local · ${people.length-state.profiles.length} demo</div></section><section class="card stat-card"><div class="stat-top"><span>Teams</span>${icon('shield',17)}</div><div class="stat-num numeric">${teams.length}</div><div class="stat-foot">Grouped by team name</div></section><section class="card stat-card"><div class="stat-top"><span>Team progress</span>${icon('target',17)}</div><div class="stat-num numeric">${groupPct}%</div><div class="stat-foot">Average XP progress</div></section></div>
    <div class="grid grid-2"><section class="card">${cardHeader('Individual rankings',`Earned XP / ${max} currently available`,'trophy')}<div>${people.map((p,i)=>`<div class="leader-row"><span class="rank ${i===0?'first':''}">${i+1}</span><div class="leader-main"><div class="row"><strong class="small" style="${p.id===activeProfile().id?'color:var(--green)':''}">${safe(p.name)}</strong>${p.demo?badge('DEMO','grey'):p.id===activeProfile().id?badge('YOU'):badge('LOCAL','blue')}</div><p class="tiny muted">${safe(p.team)} · ${p.pct}% of available XP</p><div class="progress leader-progress"><span style="width:${p.pct}%"></span></div></div><div class="leader-score">${p.xp} XP</div></div>`).join('')}</div></section>
    <section class="card">${cardHeader('Team rankings','Average XP percentage per eligible member','users')}<div>${teams.map((t,i)=>`<div class="leader-row"><span class="rank ${i===0?'first':''}">${i+1}</span><div class="leader-main"><strong class="small">${safe(t.name)}</strong><p class="tiny muted">${t.members.length} member${t.members.length===1?'':'s'} · averaged equally</p><div class="progress leader-progress"><span style="width:${t.pct}%"></span></div></div><div class="leader-score">${t.pct}%</div></div>`).join('')}</div><hr class="divider"><div class="notice">${icon('shield',16)} Rankings use the same available XP cap for every level, rather than total repetitions.</div></section></div>
    <section class="card">${cardHeader('Collective reward goal','Everyone contributes to the milestone','gift')}<div class="grid grid-2" style="align-items:center"><div><div class="upper amber">TEAM CELEBRATION LUNCH</div><div class="metric-line"><span class="metric-big">${groupPct}%</span><span class="muted small">of 80% goal</span></div><p class="card-sub" style="margin:7px 0 16px">Raise the overall participation average to unlock a team celebration.</p>${progress(percentOf(groupPct,80),'amber')}<p class="tiny muted" style="margin-top:8px">${Math.max(0,80-groupPct)} percentage points to the milestone</p></div><div style="padding:13px 20px;background:#302e25;border:1px solid #4a4432;border-radius:13px"><div class="row" style="color:var(--amber);margin-bottom:12px">${icon('gift',24)} <strong>TEAM GOAL</strong></div><p class="small" style="color:#d6c7a7">Rewards are examples until an organizer approves real prizes. Group progress here includes simulated people.</p></div></div></section></div>`;
  }
  function rewardsScreen(){const xp=xpFor(),rewards=state.rewards.slice().sort((a,b)=>a.xp-b.xp),claimedIds=new Set(state.claims.filter(c=>c.profileId===activeProfile().id).map(c=>c.rewardId)),next=rewards.find(r=>r.xp>xp);
    return `<div class="stack">${pageHeading('MILESTONES & PRIZES','Make progress rewarding.','Rewards unlock when you reach their XP thresholds. Claiming does not spend points.',`<button class="btn btn-outline btn-sm" data-action="reward-edit">${icon('settings',15)} Edit rewards</button>`)}<div class="grid grid-3"><section class="card stat-card"><div class="stat-top"><span>Available XP</span>${icon('bolt',17)}</div><div class="stat-num green">${xp}</div><div class="stat-foot">Earned so far, never deducted</div></section><section class="card stat-card"><div class="stat-top"><span>Rewards unlocked</span>${icon('gift',17)}</div><div class="stat-num">${rewards.filter(r=>xp>=r.xp).length} <span class="muted" style="font-size:17px">/ ${rewards.length}</span></div><div class="stat-foot">Based on current XP</div></section><section class="card stat-card"><div class="stat-top"><span>Next unlock</span>${icon('target',17)}</div><div class="stat-num amber">${next?next.xp-xp:0}</div><div class="stat-foot">${next?'XP remaining':'All milestones unlocked'}</div></section></div>
    <section class="card">${cardHeader('Your reward journey','Milestones can be adjusted in Settings','spark')}<div class="row between" style="margin-bottom:9px"><strong class="small">${xp} XP</strong><span class="small muted">800 XP full challenge target</span></div>${progress(percentOf(xp,800),'amber')}<div class="row between" style="margin-top:10px">${rewards.map(r=>`<span class="tiny ${xp>=r.xp?'amber':'muted'}">${r.xp}</span>`).join('')}</div></section>
    <div class="rewards-list">${rewards.map(r=>{const unlocked=xp>=r.xp,claimed=claimedIds.has(r.id);return `<section class="card"><div class="reward-card"><div class="reward-icon" style="${unlocked?'background:#3e3829':'background:#29333c;color:#92a2ac'}">${icon(r.icon||'gift',26)}</div><div class="reward-details"><div class="row wrap"><h3>${safe(r.name)}</h3>${unlocked?badge('UNLOCKED'):badge('LOCKED','grey')}</div><p>${safe(r.description)}</p><p class="amber weight-700">${r.xp} XP required</p></div><div class="reward-status">${claimed?badge('CLAIMED'):unlocked?`<button class="btn btn-primary btn-sm" data-action="claim" data-reward="${safe(r.id)}">Claim</button>`:`<span class="small muted">${r.xp-xp} away</span>`}</div></div></section>`}).join('')||`<div class="empty-state"><p>No rewards configured.</p></div>`}</div><div class="notice warn">${icon('info',16)} Claims are tracked locally for testing. This version does not distribute actual prizes or notify an organizer.</div></div>`;
  }
  function historyScreen(){const sessions=profileSessions().slice().sort((a,b)=>b.savedAt-a.savedAt);const times=sessions.filter(s=>s.duration>0&&s.type==='training').slice().reverse().slice(-6);const best=times.length?Math.min(...times.map(s=>s.duration)):null;const totalReps=sessions.reduce((n,s)=>n+num(s.pull)+num(s.push)+num(s.squat),0);
    return `<div class="stack">${pageHeading('PERSONAL ANALYTICS','Your progress, recorded.','Review completed workouts and personal bests.')}
    <div class="grid grid-3"><section class="card stat-card"><div class="stat-top"><span>Saved sessions</span>${icon('dumbbell',17)}</div><div class="stat-num numeric">${sessions.length}</div><div class="stat-foot">All difficulty levels</div></section><section class="card stat-card"><div class="stat-top"><span>All tracked reps</span>${icon('activity',17)}</div><div class="stat-num numeric">${totalReps.toLocaleString()}</div><div class="stat-foot">Rows/pull-ups, push-ups, squats</div></section><section class="card stat-card"><div class="stat-top"><span>Fastest timed session</span>${icon('timer',17)}</div><div class="stat-num numeric" style="font-size:22px">${best?timeFmt(best):'—'}</div><div class="stat-foot">Not comparable across levels</div></section></div>
    <div class="grid grid-2"><section class="card">${cardHeader('XP earned by week','Training weeks in the current challenge','chart')}${weekChart()}</section><section class="card">${cardHeader('Recent timed workouts','Elapsed workout times; lower is faster','timer')}${times.length>1?timeChart(times):`<div class="empty-state"><div class="empty-illustration">${icon('chart',25)}</div><strong>Not enough timed sessions</strong><p class="small">Save at least two timed training workouts to draw a chart.</p></div>`}<p class="module-note">Only compare completion times for workouts with the same level, movement variations, and equipment. This chart is a general activity trend.</p></section></div>
    <section class="card">${cardHeader('Session history',`${sessions.length} recorded workout${sessions.length===1?'':'s'}`,'calendar')}${sessions.length?`<div class="history-scroll"><table class="history-table"><thead><tr><th>Date</th><th>Session</th><th>Time</th><th>Reps</th><th>XP</th></tr></thead><tbody>${sessions.map(s=>`<tr><td>${formatDate(s.date)}</td><td>${safe(LEVELS[s.level]?.name||'Other')} ${s.type==='final'?badge('FINAL','amber'):`<span class="tiny muted">${Math.round(Number(s.scale||1)*100)}% training</span>`}</td><td class="numeric">${shortTime(s.duration)}</td><td class="numeric">${num(s.pull)+num(s.push)+num(s.squat)}</td><td class="numeric green">+${s.xp}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty-state"><div class="empty-illustration">${icon('calendar',25)}</div><strong>Your logbook is waiting</strong><p class="small">Completed workouts appear here automatically.</p><button class="btn btn-primary" data-nav="workout">Start a workout</button></div>`}</section></div>`;
  }
  function timeChart(times){const values=times.map(s=>s.duration/60);const max=Math.max(...values)*1.18||1;const pts=values.map((v,i)=>[40+i*410/Math.max(1,values.length-1),130-v/max*105]);const poly=pts.map(p=>p.join(',')).join(' ');return `<div class="chart-box"><svg viewBox="0 0 490 165" role="img" aria-label="Completion times in minutes across saved workouts"><line class="chart-grid" x1="38" y1="25" x2="469" y2="25"/><line class="chart-grid" x1="38" y1="78" x2="469" y2="78"/><line class="chart-grid" x1="38" y1="130" x2="469" y2="130"/><polyline class="chart-line" points="${poly}"/>${pts.map(([x,y],i)=>`<circle class="chart-dot" cx="${x}" cy="${y}" r="5"/><text class="chart-label" x="${x}" y="151" text-anchor="middle">#${i+1}</text>`).join('')}</svg></div>`;}

  function settingsScreen(){const p=activeProfile(),c=state.challenge;
    return `<div class="stack">${pageHeading('PERSONALIZATION','Challenge settings.','Manage local profiles, challenge details, and your saved data.')}
    <div class="grid grid-2"><section class="card">${cardHeader('Current profile','Information stored only in this browser','user')}<form data-form="profile-update" class="stack gap-12"><div class="field"><label for="profile-name">Display name</label><input id="profile-name" name="name" value="${safe(p.name)}" maxlength="40" required /></div><div class="field"><label for="profile-team">Team name</label><input id="profile-team" name="team" value="${safe(p.team)}" maxlength="40" required /></div><div class="field"><label for="profile-level">Preferred workout level</label><select id="profile-level" name="level">${Object.entries(LEVELS).map(([id,l])=>`<option value="${id}" ${p.level===id?'selected':''}>${l.name}</option>`).join('')}</select></div><div class="button-row"><button class="btn btn-primary" type="submit">${icon('save',15)} Save profile</button><button class="btn btn-outline" type="button" data-action="profiles">${icon('users',15)} Switch / add profiles</button></div></form></section>
    <section class="card">${cardHeader('Challenge configuration','Changes can affect weekly XP calculations','flag')}<form data-form="challenge-update" class="stack gap-12"><div class="field"><label for="challenge-name">Challenge name</label><input id="challenge-name" name="name" value="${safe(c.name)}" maxlength="65" required /></div><div class="field"><label for="challenge-group">Group name</label><input id="challenge-group" name="group" value="${safe(c.group)}" maxlength="50" required /></div><div class="field"><label for="challenge-date">Challenge start date (Monday)</label><input type="date" id="challenge-date" name="startDate" value="${safe(c.startDate)}" required /></div><div class="notice warn">${icon('info',16)} Seven-week format: six preparation weeks plus a final event week. Changing the start date changes how new sessions earn XP; already-awarded XP is not recalculated.</div><button class="btn btn-primary" type="submit">${icon('save',15)} Save challenge</button></form></section></div>
    <div class="grid grid-2"><section class="card">${cardHeader('Rewards and milestones',`${state.rewards.length} rewards configured`,'gift')}<p class="small muted" style="margin-bottom:16px">Set names, descriptions, icons, and XP thresholds. These settings apply to all profiles on this device.</p><button class="btn btn-outline" data-action="reward-edit">${icon('edit',17)} Manage rewards</button></section>
    <section class="card">${cardHeader('Data backup & restore','Your best protection against cleared browser storage','download')}<div class="stack gap-12"><p class="small muted">Export all profiles, sessions, XP, and reward claims as JSON. You can import them later on another device manually.</p><div class="button-row"><button class="btn btn-primary" data-action="export">${icon('download',16)} Export backup</button><button class="btn btn-outline" data-action="import">${icon('upload',16)} Import backup</button><input id="import-file" type="file" accept="application/json,.json" class="hidden" /></div><div class="notice info">${icon('lock',16)} No account or cloud database is connected. Other devices will not automatically see this data.</div></div></section></div>
    <section class="card">${cardHeader('Install on your phone','Works like an app with offline access','download')}<div class="grid grid-2"><div class="stack gap-8"><strong class="small">iPhone / iPad</strong><p class="small muted">Open the GitHub Pages site in Safari → Share → Add to Home Screen → Add.</p></div><div class="stack gap-8"><strong class="small">Android</strong><p class="small muted">Open the site in Chrome and choose Install app or Add to Home screen. Some browsers also show an Install button.</p></div></div><button class="btn btn-outline" data-action="install" style="margin-top:18px">${icon('download',17)} ${deferredInstall?'Install MERPH':'Installation help'}</button></section></div>`;
  }

  function renderModal(){if(!modal)return '';const close=`<button class="icon-button" data-action="close-modal" aria-label="Close">${icon('close',18)}</button>`;let title='',body='';if(modal.name==='profiles'){
      title='Local profiles';body=`<div class="stack gap-8">${state.profiles.map(p=>`<button class="profile-choice ${p.id===activeProfile().id?'current':''}" data-action="switch-profile" data-id="${safe(p.id)}"><span class="avatar">${safe(initials(p.name))}</span><span class="details"><strong>${safe(p.name)}</strong><small>${safe(p.team)} · ${safe(LEVELS[p.level]?.name||'Advanced')}</small></span>${p.id===activeProfile().id?icon('checkcircle',19):icon('chevron',19)}</button>`).join('')}</div><hr class="divider"><form data-form="profile-create" class="stack gap-12"><h3>Add a local test participant</h3><div class="field"><label>Participant name</label><input name="name" placeholder="e.g. Alex" maxlength="40" required autofocus /></div><div class="field"><label>Team name</label><input name="team" placeholder="e.g. North Shop" maxlength="40" required value="${safe(activeProfile().team)}" /></div><button type="submit" class="btn btn-primary btn-wide">${icon('plus',16)} Create and switch</button></form><button class="btn btn-outline btn-wide" data-nav="settings" style="margin-top:12px">${icon('settings',16)} Open profile & challenge settings</button><p class="module-note" style="margin-top:16px">Profiles share this browser, not a server. Use a separate device only after cloud syncing is added.</p>`;
    }else if(modal.name==='reward-edit'){
      title='Manage reward milestones';body=`<div class="stack gap-8">${state.rewards.slice().sort((a,b)=>a.xp-b.xp).map(r=>`<div class="reward-card" style="padding:10px;border:1px solid var(--border);border-radius:11px"><span class="reward-icon">${icon(r.icon||'gift',21)}</span><div class="reward-details"><strong>${safe(r.name)}</strong><p>${r.xp} XP · ${safe(r.description)}</p></div><button class="icon-button" data-action="reward-edit-one" data-id="${safe(r.id)}" aria-label="Edit ${safe(r.name)}">${icon('edit',16)}</button></div>`).join('')}</div><button class="btn btn-primary btn-wide" style="margin-top:18px" data-action="reward-edit-one" data-id="new">${icon('plus',16)} Add reward</button>`;
    }else if(modal.name==='reward-edit-one'){
      const r=state.rewards.find(v=>v.id===modal.id)||{id:'new',name:'',description:'',xp:200,icon:'gift'};
      title=modal.id==='new'?'Add reward':'Edit reward';body=`<form data-form="reward-update" class="stack gap-12"><input type="hidden" name="id" value="${safe(r.id)}" /><div class="field"><label>Reward name</label><input name="name" maxlength="40" required value="${safe(r.name)}" placeholder="Reward name" /></div><div class="field"><label>Description / prize</label><input name="description" maxlength="100" required value="${safe(r.description)}" placeholder="What the participant earns" /></div><div class="form-grid"><div class="field"><label>XP threshold</label><input name="xp" type="number" step="10" min="0" max="100000" required value="${r.xp}" /></div><div class="field"><label>Icon</label><select name="icon">${['gift','medal','coffee','shirt','trophy','spark','target'].map(i=>`<option value="${i}" ${r.icon===i?'selected':''}>${i.charAt(0).toUpperCase()+i.slice(1)}</option>`).join('')}</select></div></div><div class="modal-actions">${modal.id==='new'?'':`<button type="button" class="btn btn-danger" data-action="reward-delete" data-id="${safe(r.id)}">${icon('trash',15)} Delete</button>`}<button type="submit" class="btn btn-primary">${icon('save',15)} Save reward</button></div></form>`;
    }else if(modal.name==='activity'){
      const name=modal.kind==='checkin'?'Weekly progress check-in':'Recovery / mobility log';title=name;body=`<form data-form="activity" class="stack gap-12"><p class="muted small">Log this activity once during the current training week for 10 XP.</p><div class="field"><label>${modal.kind==='checkin'?'Progress or goal notes':'What recovery work did you do?'}</label><textarea name="notes" maxlength="500" required placeholder="${modal.kind==='checkin'?'What went well this week?':'e.g. 15 minutes of stretching or an easy walk'}"></textarea></div><div class="modal-actions"><button type="button" class="btn btn-outline" data-action="close-modal">Cancel</button><button type="submit" class="btn btn-primary">${icon('check',16)} Log +10 XP</button></div></form>`;
    }else if(modal.name==='install'){
      title='Install MERPH';body=`<div class="stack gap-12"><div class="notice info">${icon('info',17)} GitHub Pages provides HTTPS. Install works from the published web address, not by opening index.html as a local file.</div><h3>On iPhone</h3><p class="small muted">Open MERPH in Safari, tap Share, then Add to Home Screen and Add.</p><h3>On Android</h3><p class="small muted">Open MERPH in Chrome, open the browser menu, and choose Install app or Add to Home screen.</p><p class="small muted">Open MERPH online at least once to cache the files before testing offline.</p></div>`;
    }
    return `<div class="modal-backdrop" data-action="overlay"><div class="modal" role="dialog" aria-modal="true" aria-label="${safe(title)}"><div class="modal-heading"><h2>${safe(title)}</h2>${close}</div>${body}</div></div>`;
  }

  function stopTimer(w){if(w.runningSince){w.elapsedMs=num(w.elapsedMs)+Math.max(0,Date.now()-w.runningSince);w.runningSince=null;}}
  function tick(){document.querySelectorAll('[data-timer-time]').forEach(el=>el.textContent=timeFmt(elapsed(activeWorkout())));}
  function hasProgress(w){return percent(w)>0||w.elapsedMs>0||!!w.runningSince||!!w.notes;}
  function finishWorkout(){const w=activeWorkout(),lv=levelFor(w),pid=activeProfile().id;if(percent(w)!==100){toast('Check both runs and all repetition targets first.',true);return;}stopTimer(w);const week=weekNow(),training=trainingCount(pid,week),isPrep=week>=0&&week<6,firstFinal=!profileSessions(pid).some(s=>s.type==='final'&&s.xp>0);let xp=0;
    if(w.type==='training'&&isPrep){if(training<3)xp=20;if(training===2)xp+=20;}
    if(w.type==='final'&&week===6&&firstFinal){xp=175+(w.notes.trim()?25:0);}
    const entry={id:uid(),profileId:pid,date:today(),savedAt:Date.now(),week,type:w.type,level:w.level,scale:w.type==='training'?Number(w.scale||.25):1,vest:!!w.vest,vestWeight:Number(w.vestWeight)||0,duration:elapsed(w),pull:repTotal(w,'pull'),push:repTotal(w,'push'),squat:repTotal(w,'squat'),firstRun:w.first,lastRun:w.last,rounds:doneCount(w),notes:String(w.notes||'').slice(0,2000),xp};
    state.sessions.push(entry);state.workouts[pid]=makeWorkout({...activeProfile(),level:w.level});persist();render();toast(`Workout saved! ${xp>0?`+${xp} XP earned.`:'No XP awarded for this session.'}`);navigate('history');
  }
  function addActivity(kind,notes){const week=weekNow(),pid=activeProfile().id;if(week<0||week>=6||activityExists(pid,week,kind)) {toast('This activity is not eligible for XP right now.',true);return;}state.activities.push({id:uid(),profileId:pid,kind,week,date:today(),savedAt:Date.now(),xp:10,notes:String(notes).slice(0,500)});modal=null;persist();render();toast('Check-in recorded. +10 XP!');}
  function exportBackup(){const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`merph-backup-${today()}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup downloaded. Store it somewhere safe.');}
  function validateImport(data){if(!data||data.schema!==1||!Array.isArray(data.profiles)||!data.profiles.length||data.profiles.length>100||!data.profiles.every(p=>typeof p.id==='string'&&typeof p.name==='string'&&typeof p.level==='string')||!Array.isArray(data.sessions)||data.sessions.length>10000||!Array.isArray(data.activities)||data.activities.length>10000||!data.challenge||!/^\d{4}-\d{2}-\d{2}$/.test(data.challenge.startDate)||!Array.isArray(data.rewards)||data.rewards.length>100||!Array.isArray(data.claims)||!data.workouts||typeof data.workouts!=='object')return false;return true;}
  function updateFromForm(form){const values=Object.fromEntries(new FormData(form));if(form.dataset.form==='profile-update'){
      const p=activeProfile(),level=LEVELS[values.level]?values.level:'advanced';if(!values.name?.trim()||!values.team?.trim())return;if(p.level!==level&&hasProgress(activeWorkout())&&!confirm('Changing the preferred level resets your unsaved workout. Continue?'))return;p.name=values.name.trim().slice(0,40);p.team=values.team.trim().slice(0,40);p.level=level;if(activeWorkout().level!==level)state.workouts[p.id]=makeWorkout(p);persist();render();toast('Profile saved.');
    }else if(form.dataset.form==='profile-create'){
      if(!values.name?.trim()||!values.team?.trim())return;const p={id:uid(),name:values.name.trim().slice(0,40),team:values.team.trim().slice(0,40),level:'beginner'};state.profiles.push(p);state.activeProfileId=p.id;state.workouts[p.id]=makeWorkout(p);modal=null;persist();render();toast(`Profile created: ${p.name}`);
    }else if(form.dataset.form==='challenge-update'){
      if(!values.name?.trim()||!values.group?.trim()||!/^\d{4}-\d{2}-\d{2}$/.test(values.startDate))return;if(new Date(toUTC(values.startDate)).getUTCDay()!==1){toast('Choose a Monday as the start date.',true);return;}if(values.startDate!==state.challenge.startDate&&state.sessions.some(s=>s.xp>0)&&!confirm('You have awarded XP records. Changing the challenge start does NOT recalculate existing XP. Continue?'))return;state.challenge.name=values.name.trim().slice(0,65);state.challenge.group=values.group.trim().slice(0,50);state.challenge.startDate=values.startDate;persist();render();toast('Challenge settings saved.');
    }else if(form.dataset.form==='reward-update'){
      const xp=Number(values.xp);if(!Number.isInteger(xp)||xp<0||xp>100000||!values.name?.trim()||!values.description?.trim())return;const data={name:values.name.trim().slice(0,40),description:values.description.trim().slice(0,100),xp,icon:ICONS[values.icon]?values.icon:'gift'};if(values.id==='new'){state.rewards.push({id:uid(),...data});}else{const r=state.rewards.find(r=>r.id===values.id);if(!r)return;Object.assign(r,data);}modal={name:'reward-edit'};persist();render();toast('Reward milestone saved.');
    }else if(form.dataset.form==='activity'){
      if(!values.notes?.trim())return;addActivity(modal.kind,values.notes.trim());}
  }
  function onAction(button,e){const action=button.dataset.action, w=activeWorkout();switch(action){
      case 'profiles':modal={name:'profiles'};break;
      case 'close-modal':modal=null;break;
      case 'overlay':if(e.target===button)modal=null;else return;break;
      case 'switch-profile':if(state.profiles.some(p=>p.id===button.dataset.id)){state.activeProfileId=button.dataset.id;modal=null;persist();}break;
      case 'timer-toggle':if(w.runningSince)stopTimer(w);else w.runningSince=Date.now();persist();break;
      case 'timer-reset':if(confirm('Reset only the stopwatch? Your recorded rounds and repetitions will remain.')){w.runningSince=null;w.elapsedMs=0;persist();}else return;break;
      case 'reset-workout':if(confirm('Discard the current unsaved workout, including the timer, checked rounds, and notes?')){state.workouts[activeProfile().id]=makeWorkout({...activeProfile(),level:w.level});persist();}else return;break;
      case 'level':if(w.level!==button.dataset.level&&LEVELS[button.dataset.level]){if(hasProgress(w)&&!confirm('Changing levels discards the current unsaved workout. Continue?'))return;const p=activeProfile();p.level=button.dataset.level;state.workouts[p.id]=makeWorkout(p);persist();}break;
      case 'workout-type':if(w.type!==button.dataset.type){if(hasProgress(w)&&!confirm('Changing workout type discards this unsaved workout. Continue?'))return;state.workouts[activeProfile().id]={...makeWorkout({...activeProfile(),level:w.level}),type:button.dataset.type};persist();}break;
      case 'scale':{const scale=Number(button.dataset.scale);if(w.type!=='training'||![.25,.5,.75,1].includes(scale)||Number(w.scale||.25)===scale)return;if(hasProgress(w)&&!confirm('Changing training targets discards this unsaved workout. Continue?'))return;state.workouts[activeProfile().id]={...makeWorkout({...activeProfile(),level:w.level}),scale};persist();break;}
      case 'run':if(['first','last'].includes(button.dataset.run)){w[button.dataset.run]=!w[button.dataset.run];persist();}break;
      case 'round':{const index=Number(button.dataset.round);if(Number.isInteger(index)&&index>=0&&index<levelFor(w).rounds){w.rounds=w.rounds.includes(index)?w.rounds.filter(n=>n!==index):[...w.rounds,index].sort((a,b)=>a-b);persist();}break;}
      case 'reps':{const key=button.dataset.key,delta=Number(button.dataset.delta);if(['pull','push','squat'].includes(key)&&[-5,5,10].includes(delta)){w.manual[key]=clamp(num(w.manual[key])+delta,0,levelFor(w)[key]);persist();}break;}
      case 'finish-workout':finishWorkout();return;
      case 'activity':{const kind=button.dataset.kind;if(['checkin','recovery'].includes(kind)){modal={name:'activity',kind};}break;}
      case 'claim':{const r=state.rewards.find(r=>r.id===button.dataset.reward);if(!r||xpFor()<r.xp||state.claims.some(c=>c.rewardId===r.id&&c.profileId===activeProfile().id))return;state.claims.push({id:uid(),profileId:activeProfile().id,rewardId:r.id,date:today()});persist();toast(`Claim recorded: ${r.name}.`);break;}
      case 'reward-edit':modal={name:'reward-edit'};break;
      case 'reward-edit-one':modal={name:'reward-edit-one',id:button.dataset.id};break;
      case 'reward-delete':{if(!confirm('Delete this reward? Existing claim records remain in your backup but this milestone will be hidden.'))return;state.rewards=state.rewards.filter(r=>r.id!==button.dataset.id);modal={name:'reward-edit'};persist();break;}
      case 'export':exportBackup();return;
      case 'import':document.getElementById('import-file')?.click();return;
      case 'install':if(deferredInstall){deferredInstall.prompt();deferredInstall.userChoice.then(()=>{deferredInstall=null;});return;}modal={name:'install'};break;
      default:return;
    }render();
  }
  document.addEventListener('click',e=>{const nav=e.target.closest('[data-nav]');if(nav){e.preventDefault();navigate(nav.dataset.nav);return;}const action=e.target.closest('[data-action]');if(action)onAction(action,e);});
  document.addEventListener('submit',e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();updateFromForm(form);});
  document.addEventListener('change',async e=>{if(e.target.matches('[data-field="workout-notes"]')){activeWorkout().notes=e.target.value.slice(0,2000);persist();}if(e.target.matches('[data-field="vest"]')){activeWorkout().vest=e.target.checked;if(!e.target.checked)activeWorkout().vestWeight=0;persist();render();}if(e.target.matches('[data-field="vest-weight"]')){activeWorkout().vestWeight=clamp(num(e.target.value),0,150);persist();}if(e.target.id==='import-file'){
      const file=e.target.files?.[0];if(!file)return;if(file.size>2*1024*1024){toast('Backup file is too large (2MB limit).',true);return;}try{const candidate=JSON.parse(await file.text());if(!validateImport(candidate))throw new Error('Unsupported or incomplete MERPH backup');if(!confirm('Import this backup and replace all existing local MERPH data on this device?'))return;state=candidate;state.activeProfileId=state.profiles.some(p=>p.id===state.activeProfileId)?state.activeProfileId:state.profiles[0].id;for(const p of state.profiles){if(!LEVELS[p.level])p.level='advanced';if(!state.workouts[p.id])state.workouts[p.id]=makeWorkout(p);}persist();modal=null;render();toast('Backup imported successfully.');}catch(err){toast(`Import failed: ${err.message}`,true);}e.target.value='';
    }});
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal){modal=null;render();}});
  window.addEventListener('hashchange',()=>{const hash=location.hash.slice(1);if(navs().some(n=>n.id===hash)&&hash!==page){page=hash;modal=null;render();}});
  window.addEventListener('online',()=>{online=true;render();toast('Back online. Your workout was saved locally.');});
  window.addEventListener('offline',()=>{online=false;render();toast('Offline mode. Workout tracking still works.');});
  window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;});
  window.addEventListener('appinstalled',()=>{deferredInstall=null;toast('MERPH was installed successfully!');});
  if('serviceWorker' in navigator&&location.protocol!=='file:'){
    window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js',{scope:'./'}).catch(err=>console.warn('Service worker unavailable:',err)));
  }
  // Elapsed time is derived from wall-clock timestamps so backgrounding the PWA doesn't pause the timer.
  setInterval(tick,250);
  render();
})();
